import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color, PointLight } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  const timelines = [];
  const primitiveResults = [];

  // Configuration
  const colors = config.colors || {
    background: '#0b0b10',
    accent: '#ff2a38',
    paper: '#e8ecf2'
  };

  // ===== 1. Main parallax plane with displacement =====
  const planeGeo = new PlaneGeometry(4.0, 2.5, 64, 64);

  const planeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    metalness: 0.05,
    roughness: 0.8,
    transparent: true,
    opacity: 0,
    toneMapped: true
  });

  const planeMesh = new Mesh(planeGeo, planeMat);
  root.add(planeMesh);

  // Async texture loading
  Promise.all([
    ctx.textureLoader.loadTexture(config.imageUrl),
    ctx.textureLoader.loadTexture(config.depthMapUrl)
  ]).then(([imgTex, depthTex]) => {
    planeMat.map = imgTex;
    planeMat.displacementMap = depthTex;
    planeMat.displacementScale = 0.18;
    planeMat.needsUpdate = true;
  }).catch(err => console.error('Texture load error:', err));

  // ===== 2. Caption block with stacked text =====
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const typography = config.typography || {};

  const captionBlock = new Group();
  captionBlock.position.set(-1.5, -1.15, 0.1); // Start 0.4 units lower
  root.add(captionBlock);

  let yOffset = 0;
  for (const item of textContent) {
    const role = item.role || 'body';
    const fontSize = typography[role]?.fontSize || 12;

    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: colors.paper,
      align: 'left'
    });
    textMesh.position.y = yOffset;
    captionBlock.add(textMesh);
    yOffset -= 0.25;
  }

  // ===== 3. Accent hairline bar (between headline and body) =====
  const accentGeo = new PlaneGeometry(0.75, 0.02);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 0.4,
    transparent: true,
    opacity: 0
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.375, 0.15); // Between headline (-0.25) and body (-0.50)
  captionBlock.add(accentBar);

  // ===== 4. Bottom scrim gradient =====
  const scrimGeo = new PlaneGeometry(8, 1.5);
  const scrimMat = new MeshStandardNodeMaterial({
    color: new Color(colors.background),
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 0
  });
  const scrimMesh = new Mesh(scrimGeo, scrimMat);
  scrimMesh.position.set(0, -1.25, 0.05);
  root.add(scrimMesh);

  // ===== 5. Lights for subject separation =====
  const rimLight = new PointLight(colors.accent, 0.8, 10);
  rimLight.position.set(-2.0, 1.5, 1.5);
  root.add(rimLight);

  const keyLight = new PointLight(0xffffff, 0.6, 15);
  keyLight.position.set(1.5, 1.2, 2.0);
  root.add(keyLight);

  // ===== 6. Animation timelines =====

  // Plate mount fade-in: 500ms cubic-bezier(0.25,0.46,0.45,0.94)
  const plateTl = gsap.timeline();
  plateTl.to(planeMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
  }, 0);
  timelines.push(plateTl);

  // Caption block rise-in: 700ms cubic-bezier(0.215,0.61,0.355,1) starting 120ms after plate
  const captionTl = gsap.timeline();
  captionTl.to(captionBlock.position, {
    y: -0.75, // Rise from -1.15 to -0.75 (0.4 unit displacement)
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
  }, 0.12);

  captionTl.to([accentMat, scrimMesh.material], {
    opacity: 1,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
  }, 0.12);

  timelines.push(captionTl);

  // ===== 7. Apply parallax-scroll primitive =====
  const parallaxRes = ctx.primitives['parallax-scroll'](root, { intensity: 0.35 });
  if (parallaxRes?.cleanup) {
    primitiveResults.push(parallaxRes.cleanup);
  }

  // ===== 8. Cleanup handler =====
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    [planeGeo, accentGeo, scrimGeo].forEach(g => g.dispose());
    [planeMat, accentMat, scrimMat].forEach(m => m.dispose());
    primitiveResults.forEach(fn => typeof fn === 'function' && fn());
  };

  return root;
}
